args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?personLabel ?b ?d ?lifespanDays WHERE {
  VALUES ?person { dbr:Silas_Hardy dbr:Lee_Mantle }
  OPTIONAL { ?person dbo:birthDate ?b. }
  OPTIONAL { ?person dbp:birthDate ?b2. }
  OPTIONAL { ?person dbo:deathDate ?d. }
  OPTIONAL { ?person dbp:deathDate ?d2. }
  BIND(COALESCE(?b, ?b2) AS ?b)
  BIND(COALESCE(?d, ?d2) AS ?d)
  FILTER(BOUND(?b) && BOUND(?d))
  BIND(((YEAR(?d) - YEAR(?b)) * 365 + (MONTH(?d) - MONTH(?b)) * 30 + (DAY(?d) - DAY(?b))) AS ?lifespanDays)
  OPTIONAL { ?person rdfs:label ?personLabel . FILTER(lang(?personLabel) = 'en') }
}
ORDER BY DESC(?lifespanDays)
LIMIT 2

